import React from 'react';
import { Box, Chip, IconButton, Stack, Typography } from '@mui/material';
import BoltRounded from '@mui/icons-material/BoltRounded';
import DarkModeRounded from '@mui/icons-material/DarkModeRounded';
import LightModeRounded from '@mui/icons-material/LightModeRounded';
import ShieldRounded from '@mui/icons-material/ShieldRounded';
import { alpha, useTheme } from '@mui/material/styles';

import SearchInput from './SearchInput';
import { glassPanel } from '../theme/webTheme';

export default function Navbar({
  source,
  destination,
  onSourceChange,
  onDestinationChange,
  onSearch,
  onSwap,
  loading,
  statusMessage,
  themeMode,
  onThemeModeChange,
}) {
  const theme = useTheme();

  return (
    <Box
      sx={{
        position: 'relative',
        zIndex: 10,
        mb: { xs: 2.25, md: 2.75 },
        borderRadius: 4,
        p: { xs: 2.25, md: 3 },
        overflow: 'hidden',
        ...glassPanel(theme, 0.82),
      }}
    >
      <Box
        sx={{
          position: 'absolute',
          inset: 0,
          background:
            theme.palette.mode === 'dark'
              ? 'radial-gradient(circle at top left, rgba(37,99,235,0.18), transparent 38%), radial-gradient(circle at right, rgba(45,212,191,0.16), transparent 32%)'
              : 'radial-gradient(circle at top left, rgba(59,130,246,0.16), transparent 36%), radial-gradient(circle at right, rgba(20,184,166,0.16), transparent 28%)',
          pointerEvents: 'none',
        }}
      />

      <Stack spacing={3} sx={{ position: 'relative' }}>
        <Stack direction={{ xs: 'column', lg: 'row' }} spacing={2.5} alignItems={{ lg: 'flex-start' }} justifyContent="space-between">
          <Stack spacing={1.25} sx={{ flex: 1 }}>
            <Stack direction="row" spacing={1} flexWrap="wrap">
              <Chip 
                label="5G Ready" 
                icon={<BoltRounded sx={{ fontSize: 16 }} />} 
                size="small"
                sx={{ 
                  backgroundColor: alpha('#00F5D4', 0.15),
                  color: '#00F5D4',
                  fontWeight: 700,
                  '& .MuiChip-icon': { color: '#00F5D4' }
                }} 
              />
              <Chip
                label="AI Safety"
                icon={<ShieldRounded sx={{ fontSize: 16 }} />}
                size="small"
                sx={{
                  backgroundColor: alpha('#3B82F6', 0.15),
                  color: '#3B82F6',
                  fontWeight: 700,
                  '& .MuiChip-icon': { color: '#3B82F6' }
                }}
              />
            </Stack>

            <Typography variant="h2">Safe Route Navigator</Typography>
            <Typography variant="body1" sx={{ maxWidth: 600, color: 'text.secondary', lineHeight: 1.6 }}>
              Find the safest routes in Bangalore using real-time crime data and AI-powered risk assessment.
            </Typography>
          </Stack>

          <IconButton
            onClick={() => onThemeModeChange(themeMode === 'dark' ? 'light' : 'dark')}
            sx={{
              width: 48,
              height: 48,
              borderRadius: '14px',
              backgroundColor: theme.palette.mode === 'dark' ? alpha('#1E293B', 0.8) : alpha('#FFFFFF', 0.9),
              border: `1px solid ${alpha(theme.palette.divider, 0.5)}`,
              color: theme.palette.text.primary,
              flexShrink: 0,
              '&:hover': {
                backgroundColor: theme.palette.mode === 'dark' ? alpha('#334155', 0.9) : alpha('#F1F5F9', 0.95),
                transform: 'scale(1.05)',
              },
              transition: 'all 200ms ease',
            }}
          >
            {themeMode === 'dark' ? <LightModeRounded /> : <DarkModeRounded />}
          </IconButton>
        </Stack>

        <SearchInput
          source={source}
          destination={destination}
          onSourceChange={onSourceChange}
          onDestinationChange={onDestinationChange}
          onSearch={onSearch}
          onSwap={onSwap}
          loading={loading}
          statusMessage={statusMessage}
        />
      </Stack>
    </Box>
  );
}
